Ваш бэкенд проверяет `hash` через HMAC-SHA256 с токеном бота. Партнёр проверяет `signature` через Ed25519: ему нужны публичный ключ Telegram и ID вашего бота.

Зависимость: `pip install cryptography`.

```python
import base64
import hmac
import json
import time
from urllib.parse import parse_qsl

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey


# Публичный ключ Telegram для production.
TELEGRAM_KEY = Ed25519PublicKey.from_public_bytes(bytes.fromhex(
    "e7bf03a2fa4602af4580703d88dda5bb59f32ed8b02a56c187fe7d34caed242d"
))


def _parse(raw: str) -> dict:
    pairs = parse_qsl(
        raw,
        keep_blank_values=True,
        strict_parsing=True,
        encoding="utf-8",
        errors="strict",
        max_num_fields=100,
    )
    data = dict(pairs)
    if len(data) != len(pairs):
        raise ValueError("Повторяющиеся параметры initData")
    return data


def _data_check_string(data: dict, excluded: set) -> bytes:
    return "\n".join(
        f"{key}={data[key]}"
        for key in sorted(data)
        if key not in excluded
    ).encode("utf-8")


def _checked_user(data: dict, max_age: int) -> dict:
    # Вызывается только после успешной проверки подписи.
    try:
        auth_date = int(data["auth_date"])
        user = json.loads(data["user"])
    except (KeyError, ValueError) as exc:
        raise ValueError("Некорректные auth_date или user") from exc

    now = int(time.time())
    if not now - max_age <= auth_date <= now + 30:
        raise ValueError("initData устарела или дата в будущем")

    if (
        not isinstance(user, dict)
        or type(user.get("id")) is not int
        or user["id"] <= 0
    ):
        raise ValueError("Некорректный пользователь")
    return user


def verify_backend(
    raw: str, bot_token: str, *, max_age: int = 300
) -> dict:
    data = _parse(raw)
    try:
        received_hash = bytes.fromhex(data["hash"])
    except (KeyError, ValueError) as exc:
        raise ValueError("Некорректный hash") from exc

    # Ключ первого HMAC — именно b"WebAppData".
    secret = hmac.digest(b"WebAppData", bot_token.encode("utf-8"), "sha256")
    expected = hmac.digest(
        secret,
        _data_check_string(data, {"hash"}),
        "sha256",
    )
    if not hmac.compare_digest(expected, received_hash):
        raise ValueError("Неверный hash")

    return _checked_user(data, max_age)


def verify_partner(
    raw: str, expected_bot_id: int, *, max_age: int = 300
) -> dict:
    data = _parse(raw)
    try:
        encoded = data["signature"]
        signature = base64.b64decode(
            encoded + "=" * (-len(encoded) % 4),
            altchars=b"-_",
            validate=True,
        )
        message = (
            f"{expected_bot_id}:WebAppData\n".encode("utf-8")
            + _data_check_string(data, {"hash", "signature"})
        )
        TELEGRAM_KEY.verify(signature, message)
    except (KeyError, ValueError, InvalidSignature) as exc:
        raise ValueError("Неверная или отсутствующая signature") from exc

    return _checked_user(data, max_age)
```

Передавайте исходную строку `Telegram.WebApp.initData`. Токен и ожидаемый `bot_id` берите из серверной конфигурации. Функции возвращают проверенного пользователя; `ValueError` означает отказ в аутентификации, обычно HTTP 401.

Для HMAC исключается только `hash`; для Ed25519 — оба поля `hash` и `signature`. JSON пользователя нельзя пересобирать перед проверкой. Срок действия здесь — 5 минут; в пределах этого времени данные можно использовать повторно, поэтому одноразовые операции требуют отдельной защиты от повторов.
